@Test
public void testCoDelScheduling() throws Exception {
    CoDelEnvironmentEdge envEdge = new CoDelEnvironmentEdge();
    envEdge.threadNamePrefixs.add("RpcServer.CodelFPBQ.default.handler");
    envEdge.threadNamePrefixs.add("RpcServer.CodelRWQ.default.handler");
    Configuration schedConf = HBaseConfiguration.create();
    schedConf.setInt(RpcScheduler.IPC_SERVER_MAX_CALLQUEUE_LENGTH, 250);
    schedConf.set(RpcExecutor.CALL_QUEUE_TYPE_CONF_KEY, RpcExecutor.CALL_QUEUE_TYPE_CODEL_CONF_VALUE);
    PriorityFunction priority = mock(PriorityFunction.class);
    when(priority.getPriority(any(RPCProtos.RequestHeader.class), any(Message.class), any(User.class))).thenReturn(HConstants.NORMAL_QOS);
    SimpleRpcScheduler scheduler = new SimpleRpcScheduler(schedConf, 1, 1, 1, priority, HConstants.QOS_THRESHOLD);
    try {
        // Loading mocked call runner can take a good amount of time the first time through (haven't looked why).
        // Load it for first time here outside of the timed loop.
        getMockedCallRunner(System.currentTimeMillis(), 2);
        scheduler.start();
        EnvironmentEdgeManager.injectEdge(envEdge);
        envEdge.offset = 5;
        // Calls faster than min delay
        // LOG.info("Start");
        for (int i = 0; i < 100; i++) {
            long time = System.currentTimeMillis();
            envEdge.timeQ.put(time);
            long now = System.currentTimeMillis();
            CallRunner cr = getMockedCallRunner(time, 2);
            // LOG.info("" + i + " " + (System.currentTimeMillis() - now) + " cr=" + cr);
            scheduler.dispatch(cr);
        }
        // LOG.info("Loop done");
        // make sure fast calls are handled
        waitUntilQueueEmpty(scheduler);
        Thread.sleep(100);
        assertEquals("None of these calls should have been discarded", 0, scheduler.getNumGeneralCallsDropped());
        envEdge.offset = 151;
        // calls slower than min delay, but not individually slow enough to be dropped
        for (int i = 0; i < 20; i++) {
            long time = System.currentTimeMillis();
            envEdge.timeQ.put(time);
            CallRunner cr = getMockedCallRunner(time, 2);
            scheduler.dispatch(cr);
        }
        // make sure somewhat slow calls are handled
        waitUntilQueueEmpty(scheduler);
        Thread.sleep(100);
        assertEquals("None of these calls should have been discarded", 0, scheduler.getNumGeneralCallsDropped());
        envEdge.offset = 2000;
        // now slow calls and the ones to be dropped
        for (int i = 0; i < 60; i++) {
            long time = System.currentTimeMillis();
            envEdge.timeQ.put(time);
            CallRunner cr = getMockedCallRunner(time, 100);
            scheduler.dispatch(cr);
        }
        // make sure somewhat slow calls are handled
        waitUntilQueueEmpty(scheduler);
        Thread.sleep(100);
        assertTrue("There should have been at least 12 calls dropped however there were " + scheduler.getNumGeneralCallsDropped(), scheduler.getNumGeneralCallsDropped() > 12);
    } finally {
        scheduler.stop();
    }
}

